function D.CategoryPoints(rank, plus)
    if not rank or rank < 1 or rank > 7 then return 0 end
    local offset = 0
    for step = rank + 1, 7 do
        offset = offset + (9 - step)
    end
    return 10 * (offset + (plus or 0) + 1)
end

