local byte, char, rep, concat, floor, band, gmatch = string.byte, string.char, string.rep, table.concat, math.floor, bit.band,
    string.gmatch
local BIT = { 1, 2, 4, 8, 16, 32, 64, 128 }

local function Bitmap(packed)
    local parts, chunk, size = {}, {}, 0
    local at, value = 0, 0
    local function Flush()
        if size > 0 then
            parts[#parts + 1] = char(unpack(chunk, 1, size))
            size = 0
        end
    end
    local function Put(b)
        size = size + 1
        chunk[size] = b
        if size == 64 then
            Flush()
        end
    end
    local function Add(id)
        local index = floor(id / 8)
        if index > at then
            Put(value)
            local zeros = index - at - 1
            if zeros > 64 then
                Flush()
                parts[#parts + 1] = rep("\0", zeros)
            else
                for _ = 1, zeros do
                    Put(0)
                end
            end
            at, value = index, 0
        end
        value = value + BIT[id % 8 + 1]
    end
    local last, gap, n = 0, nil, 0
    for i = 1, #packed do
        local c = byte(packed, i)
        if c >= 97 then
            n = n * 26 + c - 97
        else
            n = n * 26 + c - 65
            if gap then
                for id = last + gap, last + gap + n do
                    Add(id)
                end
                last, gap = last + gap + n, nil
            else
                gap = n
            end
            n = 0
        end
    end
    Put(value)
    Flush()
    return concat(parts)
end

local NEUTRAL = Bitmap("")

function D.Neutral(spellId)
    local b = spellId and byte(NEUTRAL, floor(spellId / 8) + 1)
    return b ~= nil and band(b, BIT[spellId % 8 + 1]) ~= 0
end

