local function StageOk(info, stage)
    return (not info.minStage or info.minStage <= stage) and (not info.maxStage or info.maxStage >= stage)
end

function D.DummyOption(option, raw, stage)
    local count = option.list and #option.list or option.n
    if not raw or raw < 1 or raw > count or raw ~= math.floor(raw) then return option.def end
    local info = option.list and option.list[raw]
    if info and stage and not StageOk(info, stage) then
        for i, other in ipairs(option.list) do
            if i ~= raw and other.rid == info.rid and StageOk(other, stage) then return i end
        end
        return option.def
    end
    return raw
end
